// ============================================================================
// FAO HITL Notifier (fao_hitl_gateway_v1) - Validate Payload
// ----------------------------------------------------------------------------
// FAO-GOV-007: the notifier input is exactly {hitl_id, kind, level}:
//   kind REQUESTED with level 0 (first notice of a new request), or
//   kind ESCALATED with level 1 (escalation to the process owner's target).
// Nothing else is read. Request content, approver names, the approval link
// and the Slack settings all come from fao_notification_context, so a caller
// cannot change what is posted or where it links.
// ============================================================================

const items = $input.all();
if (items.length !== 1) {
  throw new Error('FAO-GOV-007 notifier: payload invalid (expected exactly one item)');
}

const input = (items[0] && items[0].json) || {};
const hitl_id = input.hitl_id;
const kind = input.kind;
const level = input.level;

if (!Number.isSafeInteger(hitl_id) || hitl_id < 1) {
  throw new Error('FAO-GOV-007 notifier: hitl_id invalid');
}
if (kind !== 'REQUESTED' && kind !== 'ESCALATED') {
  throw new Error('FAO-GOV-007 notifier: kind invalid');
}
const expected_level = kind === 'REQUESTED' ? 0 : 1;
if (level !== expected_level) {
  throw new Error('FAO-GOV-007 notifier: level invalid');
}

return [{ json: { hitl_id, kind, level } }];

// ============================================================================
// FAO HITL Notifier - Compose Slack Message
// ----------------------------------------------------------------------------
// FAO-GOV-004 / FAO-GOV-007: builds the Slack chat.postMessage request from
// the fao_notification_context result only.
//   - One link: r.approval_url, the approval page for this request. The page
//     signs the approver in and records the decision through fao_hitl_decide
//     with the approver's own session; the link carries no identity and no
//     decision.
//   - REQUESTED names the eligible approvers from r.approver_candidates (the
//     database excludes the invoker). ESCALATED names r.target_name.
//   - Every dynamic value passes slackEscape() so stored text cannot form
//     Slack markup, mentions or extra links.
//   - The API URL is r.slack_api_base_url + '/chat.postMessage', so the same
//     export posts to Slack live and to a local mock in tests.
// ============================================================================

const r = (($input.first() || {}).json || {}).r;
if (!r || typeof r !== 'object' || r.ok !== true || r.send !== true) {
  throw new Error('FAO-GOV-007 notifier: notification context is not sendable');
}

function slackEscape(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const HTTP_URL = /^https?:\/\/[^\s<>|]+$/;
if (typeof r.approval_url !== 'string' || !HTTP_URL.test(r.approval_url)) {
  throw new Error('FAO-GOV-007 notifier: approval_url invalid');
}
if (typeof r.slack_api_base_url !== 'string' || !HTTP_URL.test(r.slack_api_base_url)) {
  throw new Error('FAO-GOV-007 notifier: slack_api_base_url invalid');
}
if (typeof r.slack_channel_id !== 'string' || r.slack_channel_id === '') {
  throw new Error('FAO-GOV-007 notifier: slack_channel_id invalid');
}
if (r.kind !== 'REQUESTED' && r.kind !== 'ESCALATED') {
  throw new Error('FAO-GOV-007 notifier: kind invalid');
}

const kind = r.kind;
const level = r.level;
const hitl_id = r.hitl_id;

// Escalated assets: objects {asset, policy_outcome, policy_sub_tier,
// band_status} from the rollup, or plain symbols.
const assets = Array.isArray(r.escalated_assets) ? r.escalated_assets : [];
const asset_text = assets.length === 0
  ? '(none listed)'
  : assets.map(a => {
      if (a !== null && typeof a === 'object') {
        const parts = [a.policy_outcome, a.policy_sub_tier]
          .filter(p => p !== null && p !== undefined && p !== '');
        return slackEscape(a.asset) + (parts.length ? ' (' + parts.map(slackEscape).join('/') + ')' : '');
      }
      return slackEscape(a);
    }).join(', ');

const candidates = Array.isArray(r.approver_candidates) ? r.approver_candidates : [];
const candidate_text = candidates.length === 0
  ? '(no eligible approver found)'
  : candidates.map(c => slackEscape(c && typeof c === 'object' ? c.name : c)).join(', ');

const agent_label = slackEscape(r.agent_name || r.agent_id);
const header = kind === 'ESCALATED'
  ? `*Escalation: approval request ${slackEscape(hitl_id)} for ${agent_label} needs attention*`
  : `*Approval required: request ${slackEscape(hitl_id)} for ${agent_label}*`;

const lines = [
  header,
  '',
  `*Agent:* ${slackEscape(r.agent_id)}`,
  `*Risk tier:* ${slackEscape(r.risk_tier)}`,
  `*Review sub-tier:* ${slackEscape(r.sub_tier)}`,
  `*Decide by:* ${slackEscape(r.timeout_at)}`,
  `*Escalated assets:* ${asset_text}`
];

if (kind === 'ESCALATED') {
  lines.push(`*Escalation target:* ${slackEscape(r.target_name)}`);
} else {
  lines.push(`*Eligible approvers:* ${candidate_text}`);
}

lines.push(
  '',
  `<${slackEscape(r.approval_url)}|Open the approval page>`,
  '',
  '_Sign in on the approval page to approve or reject. The person who started the run cannot decide it._'
);

const text = lines.join('\n');
const url = r.slack_api_base_url.replace(/\/+$/, '') + '/chat.postMessage';

return [{
  json: {
    hitl_id,
    kind,
    level,
    url,
    body: { channel: r.slack_channel_id, text, mrkdwn: true }
  }
}];

// ============================================================================
// FAO HITL Notifier - Classify Slack Result
// ----------------------------------------------------------------------------
// FAO-GOV-007: both outputs of Slack: Post Message (success and error) feed
// this node. The attempt counts as SENT only when Slack answered HTTP 200
// with body.ok === true; anything else (HTTP error, timeout, ok:false) is
// FAILED, recorded by Record Notification, and retried by the sweep.
// The ids come from Validate Payload, never from the HTTP response.
// ============================================================================

const ids = $('Validate Payload').first().json;
const res = (($input.first() || {}).json) || {};

const clean = (s) => String(s).replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 300);

let outcome = 'FAILED';
let external_ref = null;
let error = null;

if (res.error !== undefined && res.error !== null && res.statusCode === undefined) {
  // Error output of the HTTP Request node (network error, timeout, 4xx, 5xx).
  const e = res.error;
  let msg;
  if (typeof e === 'string') msg = e;
  else if (e && typeof e === 'object') msg = e.message || e.description || e.code || 'request failed';
  else msg = 'request failed';
  const code = e && typeof e === 'object' ? (e.httpCode || e.status || e.statusCode) : undefined;
  error = code !== undefined ? `http error ${code}: ${msg}` : `http error: ${msg}`;
} else if (res.statusCode !== undefined || res.body !== undefined) {
  let body = res.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (err) { body = null; }
  }
  const status = res.statusCode;
  if (status === 200 && body !== null && typeof body === 'object' && body.ok === true) {
    outcome = 'SENT';
    external_ref = typeof body.ts === 'string' ? body.ts : null;
  } else {
    const slack_error = body !== null && typeof body === 'object' && typeof body.error === 'string'
      ? body.error : 'not ok';
    error = `slack status ${status}: ${slack_error}`;
  }
} else {
  error = 'no response from Slack';
}

return [{
  json: {
    hitl_id: ids.hitl_id,
    kind: ids.kind,
    level: ids.level,
    outcome,
    external_ref: external_ref === null ? null : clean(external_ref).slice(0, 200),
    error: error === null ? null : clean(error)
  }
}];
